// A greeting intro, timed to a measured 3.5 s UI promo: a gradient wordmark on a soft ground shrinks away as an app
// window grows in behind it; the camera pushes in tilted, types "Hello, <name>." and the question across the window in
// large perspective type, slides the suggestion cards in, then pulls back and flattens to the whole window with its
// prompt box. 1920x1080 at 60 fps.
//
// Everything you read on screen is a prop (brand, name, question, card labels, placeholder, caption, colours, font).
// The camera (camera.ts) is the reference's, tracked frame by frame and smoothed into keys; the content steps every
// second frame like the reference (the `step` prop). The window is drawn flat
// in ui.tsx; the camera tilts it with the layer's own 3D transform.
//
//   node ../kinetograph/packages/cli/dist/cli.js still templates/greeting-intro/index.tsx 120 --comp GreetingIntro -o out/f120.png
//   node ../kinetograph/packages/cli/dist/cli.js render templates/greeting-intro/index.tsx -o templates/greeting-intro/out/greeting-intro.mp4

import React from 'react';
import { z } from 'zod';
import { Composition, registerRoot, useCurrentFrame } from 'remotion';
import { Camera, Layer, Rect, Text, linearGradient, radialGradient } from '@kinetographdev/core';
import { measureText } from '@remotion/layout-utils';
import { camera } from './scenes/camera.js';
import { Window, useFont } from './scenes/ui.js';
import type { UiProps } from './scenes/ui.js';
import { ease, keys } from './scenes/shared/kit/core/timing.js';

export const W = 1920;
export const H = 1080;
export const FPS = 60;
export const DURATION = 212;

const hex = z.string().describe('A CSS colour.');

export const greetingSchema = z.object({
  brand: z.string().describe('The wordmark, also the app name at the top of the window.'),
  name: z.string().describe('Who is greeted: "Hello, <name>."'),
  question: z.string().describe('The grey line under the greeting.'),
  cards: z.array(z.string()).min(1).max(4).describe('Suggestion card labels, left to right (up to four).'),
  placeholder: z.string().describe('Placeholder of the prompt box at the bottom of the window.'),
  caption: z.string().describe('Small grey line at the bottom left of the frame. Empty for none.'),
  font: z.string().describe('Google Fonts family for all type. The reference is set in Google Sans, which Google Fonts now carries.'),
  step: z.number().int().min(1).max(4).describe('Hold every N frames. 2 reproduces the reference, which is 30 fps content shown twice; 1 is smooth 60 fps.'),
  colors: z
    .object({
      ground: hex.describe('The pale ground behind the window.'),
      glowCool: hex.describe('Soft blur at the top left of the ground.'),
      glowWarm: hex.describe('Soft blur at the bottom right of the ground.'),
      window: hex,
      sidebar: hex,
      surface: hex.describe('Cards.'),
      field: hex.describe('Prompt box.'),
      ink: hex.describe('Dark type.'),
      muted: hex.describe('Grey type and icons.'),
      greetingStart: hex.describe('Left end of the gradient on the greeting.'),
      greetingEnd: hex.describe('Right end of the gradient on the greeting.'),
      wordmark: z.array(hex).min(2).describe('Gradient stops of the wordmark, left to right.'),
    })
    .describe('Colours.'),
});
export type GreetingProps = z.infer<typeof greetingSchema>;

export const defaults: GreetingProps = {
  brand: 'Kinetograph',
  name: 'Sri',
  question: 'What are we shipping today?',
  cards: ['Ship the demo', 'Cut a launch video', 'Render the changelog', 'Draft the release post'],
  placeholder: 'Describe your video',
  caption: 'Scenes shortened and simulated.',
  font: 'Google Sans',
  step: 2,
  colors: {
    ground: '#faf9f6',
    glowCool: '#ecf0f5',
    glowWarm: '#f8eeeb',
    window: '#ffffff',
    sidebar: '#f8f6f5',
    surface: '#f4f3ef',
    field: '#f6f5f1',
    ink: '#1b1b1b',
    muted: '#85837f',
    greetingStart: '#2d6bea',
    greetingEnd: '#6a5dd0',
    wordmark: ['#396ee9', '#4e61e0', '#6557dc', '#7c52d0', '#9b42c8', '#ae3dbf', '#c834a4', '#ca348b', '#d2306d', '#d62b61', '#e0284e', '#dc1a18'],
  },
};

const rgba = (hex: string, a: number) => {
  const h = hex.replace('#', '');
  const n = parseInt(h.length === 3 ? h.replace(/./g, '$&$&') : h, 16);
  return `rgba(${(n >> 16) & 255},${(n >> 8) & 255},${n & 255},${a.toFixed(4)})`;
};

/** A soft gaussian glow: an elliptical radial gradient whose alpha falls off as exp(-d^2 / 2 sigma^2) out to 3 sigma. */
const Glow: React.FC<{ id: string; color: string; cx: number; cy: number; sx: number; sy: number }> = ({ id, color, cx, cy, sx, sy }) => (
  <Rect id={id} x={cx - 3 * sx} y={cy - 3 * sy} width={6 * sx} height={6 * sy}
    fill={radialGradient(Array.from({ length: 49 }, (_, i): [number, string] => [i / 48, rgba(color, Math.exp(-0.5 * (i / 16) ** 2))]), { cx: 0.5, cy: 0.5, r: 0.5 })} />
);

const Ground: React.FC<{ c: GreetingProps['colors'] }> = ({ c }) => (
  <Layer id="ground">
    <Rect id="ground-base" width={W} height={H} fill={c.ground} />
    <Glow id="glow-cool" color={c.glowCool} cx={583} cy={351} sx={349} sy={225} />
    <Glow id="glow-warm" color={c.glowWarm} cx={1342} cy={709} sx={350} sy={232} />
  </Layer>
);

// The wordmark: held until frame 8, then (as in the reference) it shrinks 6% a frame, rises 23 px a frame and fades
// linearly until it is gone at about frame 23.
const WORD_SIZE = 161.5;
const Wordmark: React.FC<{ text: string; stops: string[]; family: string; f: number }> = ({ text, stops, family, f }) => {
  const m = measureText({ text, fontFamily: family, fontSize: WORD_SIZE, fontWeight: '500' });
  const fit = Math.min(1, 760 / m.width);
  const k = Math.max(0, f - 8);
  const opacity = Math.max(0, 1 - 0.0655 * k);
  if (opacity <= 0) return null;
  const scale = (1 - 0.06 * k) * fit;
  const y = 570 - 23.4 * k;
  return (
    <Layer id="wordmark" x={W / 2} y={y} scale={scale} opacity={opacity}>
      <Text id="wordmark-text" font={family} weight={500} size={WORD_SIZE} x={-m.width / 2} y={-m.height * 0.56 - 19}
        color={linearGradient(stops, { angle: 90 })}>{text}</Text>
    </Layer>
  );
};

export const GreetingIntro: React.FC<GreetingProps> = (p) => {
  const frame = useCurrentFrame();
  const f = p.step > 1 ? Math.floor(frame / p.step) * p.step : frame;
  const family = useFont(p.font);
  const c = p.colors;
  const ui: UiProps = {
    font: p.font,
    appName: p.brand,
    name: p.name,
    question: p.question,
    cards: p.cards,
    placeholder: p.placeholder,
    palette: {
      ground: c.ground, glowCool: c.glowCool, glowWarm: c.glowWarm, window: c.window, windowEdge: '#ebe9e4',
      sidebar: c.sidebar, ink: c.ink, muted: c.muted, faint: '#8f8e8a', surface: c.surface, field: c.field,
      greetA: c.greetingStart, greetB: c.greetingEnd, brandStops: c.wordmark,
    },
  };
  const cam = camera(f);
  return (
    <Layer id="root">
      <Camera perspective={cam.perspective} />
      <Ground c={c} />
      <Layer id="world" x={cam.x} y={cam.y} scale={cam.s} rotation={cam.c} rotateX={cam.a} rotateY={cam.b}
        anchorX={536} anchorY={304} opacity={cam.opacity}>
        <Window f={f} ui={ui} family={family} />
      </Layer>
      <Wordmark text={p.brand} stops={c.wordmark} family={family} f={f} />
      {p.caption ? (
        <Text id="caption" font={family} size={18.8} color="#a2a2a2" x={76} y={1000} opacity={Math.min(1, Math.max(0, (f - 8) / 15))}>
          {p.caption}
        </Text>
      ) : null}
    </Layer>
  );
};

registerRoot(() => (
  <Composition id="GreetingIntro" component={GreetingIntro} schema={greetingSchema} defaultProps={defaults}
    durationInFrames={DURATION} fps={FPS} width={W} height={H} />
));

// Frame-based timing: eases, keyframes, ramps, and two smooth curves for camera paths measured key by key.

import { Easing, interpolate } from 'remotion';

export const clamp = { extrapolateLeft: 'clamp', extrapolateRight: 'clamp' } as const;
export const ease = Easing.bezier(0.45, 0, 0.15, 1);
export const easeOut = Easing.bezier(0.16, 1, 0.3, 1);
export const easeIn = Easing.bezier(0.7, 0, 0.84, 0);

/** interpolate over keyframes [[frame, value], ...] with one easing for every segment */
export function keys(f: number, k: [number, number][], easing: (t: number) => number = ease): number {
  if (f <= k[0][0]) return k[0][1];
  for (let i = 1; i < k.length; i++) {
    if (f <= k[i][0]) {
      const [a, va] = k[i - 1];
      const [b, vb] = k[i];
      return va + (vb - va) * easing((f - a) / (b - a));
    }
  }
  return k[k.length - 1][1];
}

/** from at frame a to to at frame b, held outside */
export const ramp = (f: number, a: number, b: number, from: number, to: number, easing = ease) =>
  interpolate(f, [a, b], [from, to], { ...clamp, easing });

/** A smooth curve through [frame, value] keys (cubic Hermite, finite-difference slopes, flat at the ends and where
 *  the direction turns), so a camera measured key by key moves without stopping at every key. */
export function spline(f: number, k: [number, number][]): number {
  if (f <= k[0][0]) return k[0][1];
  const n = k.length - 1;
  if (f >= k[n][0]) return k[n][1];
  const slope = (i: number) => {
    if (i === 0 || i === n) return 0;
    const a = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const b = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return a * b <= 0 ? 0 : (k[i + 1][1] - k[i - 1][1]) / (k[i + 1][0] - k[i - 1][0]);
  };
  let i = 0;
  while (f > k[i + 1][0]) i++;
  const [t0, v0] = k[i];
  const [t1, v1] = k[i + 1];
  const h = t1 - t0;
  const t = (f - t0) / h;
  const t2 = t * t;
  const t3 = t2 * t;
  return (2 * t3 - 3 * t2 + 1) * v0 + (t3 - 2 * t2 + t) * h * slope(i) + (-2 * t3 + 3 * t2) * v1 + (t3 - t2) * h * slope(i + 1);
}

/** Monotone cubic through keys [[frame, value], ...]: a camera that glides through its marks without stopping or
 *  overshooting them. */
export function glide(f: number, k: [number, number][]): number {
  const n = k.length;
  if (f <= k[0][0]) return k[0][1];
  if (f >= k[n - 1][0]) return k[n - 1][1];
  const d = k.map((_, i) => {
    if (i === 0 || i === n - 1) return 0;
    const s0 = (k[i][1] - k[i - 1][1]) / (k[i][0] - k[i - 1][0]);
    const s1 = (k[i + 1][1] - k[i][1]) / (k[i + 1][0] - k[i][0]);
    return s0 * s1 <= 0 ? 0 : (2 * s0 * s1) / (s0 + s1);
  });
  let i = 1;
  while (f > k[i][0]) i++;
  const [x0, y0] = k[i - 1];
  const [x1, y1] = k[i];
  const hh = x1 - x0;
  const t = (f - x0) / hh;
  const t2 = t * t;
  const t3 = t2 * t;
  return (
    (2 * t3 - 3 * t2 + 1) * y0 + (t3 - 2 * t2 + t) * hh * d[i - 1] + (-2 * t3 + 3 * t2) * y1 + (t3 - t2) * hh * d[i]
  );
}

// The app window the camera flies over, drawn flat in "window units": the window is WIN_W x WIN_H with its top left
// at the origin, and at the end of the shot one unit is one pixel of the 1920x1080 frame. Everything the camera does
// to it (push-in, tilt, pull-back) happens in camera.ts; this file only knows where things sit and when they appear.

import React from 'react';
import { Ellipse, Layer, Path, Rect, Text, dropShadow, linearGradient } from '@kinetographdev/core';
import { measureText } from '@remotion/layout-utils';
import { makeGoogleFont } from '@kinetographdev/core/google-fonts';

export const WIN_W = 1072;
export const WIN_H = 608;
export const SIDEBAR = 63;
export const CONTENT_X = 99;

export const CARD = { y: 266.5, w: 218, h: 131, gap: 21.7, radius: 14 };
export const INPUT = { y: 512, w: 940, h: 60 };

export interface Palette {
  ground: string;
  glowCool: string;
  glowWarm: string;
  window: string;
  windowEdge: string;
  sidebar: string;
  ink: string;
  muted: string;
  faint: string;
  surface: string;
  field: string;
  greetA: string;
  greetB: string;
  brandStops: string[];
}

export interface UiProps {
  /** The font family (Google Fonts) used for every line of UI type. */
  font: string;
  appName: string;
  /** Typed in blue: "Hello, <name>." */
  name: string;
  question: string;
  cards: string[];
  placeholder: string;
  palette: Palette;
}

/** Loads a Google font family at the weights the UI uses and returns the registered family name. */
export const useFont = (family: string): string => makeGoogleFont(family).loadFont('normal', { weights: ['400', '500'] }).fontFamily;

/** Characters shown of `text` at frame f: one every `every` frames from `start`. */
export const typed = (f: number, start: number, every: number, text: string) =>
  Math.max(0, Math.min(text.length, Math.floor((f - start) / every) + 1));

/** Reveal timings, in frames of the 60 fps reference (its content steps every second frame). */
export const T = {
  /** Frame at which each character of "Hello, <name>." has appeared (the reference types it unevenly). */
  greet: [42, 44, 46, 48, 52, 54, 58, 58, 60, 62, 64],
  questionStart: 57,
  questionEvery: 1,
  /** Cards and the prompt box cut in, one 30 fps step each. */
  cardAt: [80, 92, 104, 116],
  inputAt: 128,
};

/** Characters of a greeting shown at frame f: follows T.greet, then one every 2 frames for a longer name. */
const greetCount = (f: number, len: number) => {
  let n = 0;
  for (let i = 0; i < len; i++) {
    const t = i < T.greet.length ? T.greet[i] : T.greet[T.greet.length - 1] + 2 * (i - T.greet.length + 1);
    if (f >= t) n = i + 1;
  }
  return n;
};

const roundRectLeft = (w: number, h: number, r: number) =>
  `M ${r} 0 H ${w} V ${h} H ${r} A ${r} ${r} 0 0 1 0 ${h - r} V ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`;

export const Window: React.FC<{ f: number; ui: UiProps; family: string }> = ({ f, ui, family }) => {
  const p = ui.palette;
  const nameWidth = measureText({ text: ui.appName, fontFamily: family, fontSize: 25.5, fontWeight: '400' }).width;
  const greet = `Hello, ${ui.name}.`;
  const nGreet = greetCount(f, greet.length);
  const nQuestion = typed(f, T.questionStart, T.questionEvery, ui.question);
  const hide = (n: number) => (_c: string, i: number) => (i < n ? null : { opacity: 0 });
  return (
    <Layer id="window">
      <Rect id="win-body" width={WIN_W} height={WIN_H} radius={24} fill={p.window} stroke={{ color: p.windowEdge, width: 1.5 }}
        effects={[dropShadow({ y: 6, blur: 26, color: 'rgba(60,50,40,0.05)' })]} />
      <Path id="win-sidebar" d={roundRectLeft(SIDEBAR, WIN_H, 24)} fill={p.sidebar} />
      {[21, 49, 77].map((y) => (
        <Rect key={y} id={`burger-${y}`} x={18} y={y - 1.2} width={29} height={2.4} radius={1.2} fill={p.faint} />
      ))}
      <Ellipse id="new-chat" x={31 - 15} y={138 - 15} width={30} height={30} fill="#eeede9" />
      <Rect id="plus-h" x={31 - 4.75} y={138 - 0.9} width={9.5} height={1.8} fill={p.muted} />
      <Rect id="plus-v" x={31 - 0.9} y={138 - 4.75} width={1.8} height={9.5} fill={p.muted} />

      <Text id="app-name" font={family} weight={400} size={25.5} color={p.ink} x={CONTENT_X - 1} y={36.4}>{ui.appName}</Text>
      <Path id="app-chev" d="M 0 0 H 10 L 5 5 Z" fill={p.muted} x={CONTENT_X + 11 + nameWidth} y={50} />

      <Text id="greet" font={family} weight={400} size={41} x={CONTENT_X - 1} y={122.5}
        color={linearGradient([p.greetA, p.greetB], { angle: 90 })} chars={hide(nGreet)}>{greet}</Text>
      <Text id="question" font={family} weight={400} size={44} x={CONTENT_X - 2} y={176} color={p.muted} chars={hide(nQuestion)}>
        {ui.question}
      </Text>

      {ui.cards.map((label, i) => {
        const a = T.cardAt[i] ?? T.cardAt[T.cardAt.length - 1] + 12 * (i - T.cardAt.length + 1);
        const o = f >= a ? 1 : 0;
        const lift = 0;
        return (
          <Layer key={label + i} id={`card-${i}`} x={CONTENT_X + i * (CARD.w + CARD.gap)} y={CARD.y + lift} opacity={o}>
            <Rect id={`card-bg-${i}`} width={CARD.w} height={CARD.h} radius={CARD.radius} fill={p.surface} />
            <Text id={`card-t-${i}`} font={family} weight={400} size={19.1} color={p.ink} x={14} y={15.2}>{label}</Text>
          </Layer>
        );
      })}

      <Layer id="input" x={CONTENT_X} y={INPUT.y} opacity={f >= T.inputAt ? 1 : 0}>
        <Rect id="input-bg" width={INPUT.w} height={INPUT.h} radius={30} fill={p.field} />
        <Text id="input-t" font={family} weight={400} size={19} color={p.muted} x={24} y={19.2}>{ui.placeholder}</Text>
      </Layer>
    </Layer>
  );
};
